const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');
const config = require('./config');
const { MEDALHAS_PADRAO } = require('./regras');
const { hashSenha } = require('./senha');

fs.mkdirSync(config.PASTA_DADOS, { recursive: true });
const db = new DatabaseSync(path.join(config.PASTA_DADOS, 'maxx.db'));

// No Azure App Service a pasta de dados fica num disco de rede, onde o modo WAL do SQLite
// não é seguro; lá usamos o modo tradicional (DELETE).
const NO_AZURE = Boolean(process.env.WEBSITE_SITE_NAME);
db.exec(`PRAGMA journal_mode = ${NO_AZURE ? 'DELETE' : 'WAL'};`);
db.exec('PRAGMA busy_timeout = 5000;');

db.exec(`
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS usuarios (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  senha_hash TEXT NOT NULL,
  papel TEXT NOT NULL DEFAULT 'aluno' CHECK (papel IN ('aluno', 'professor', 'admin')),
  curso TEXT,
  bio TEXT NOT NULL DEFAULT '',
  avatar TEXT,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sessoes (
  token_hash TEXT PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  expira_em INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS posts (
  id INTEGER PRIMARY KEY,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  imagem TEXT,
  legenda TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_posts_usuario ON posts(usuario_id);

CREATE TABLE IF NOT EXISTS curtidas (
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, usuario_id)
);

CREATE TABLE IF NOT EXISTS comentarios (
  id INTEGER PRIMARY KEY,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  usuario_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  texto TEXT NOT NULL,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_comentarios_post ON comentarios(post_id);

CREATE TABLE IF NOT EXISTS tipos_medalha (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL,
  emoji TEXT NOT NULL,
  pontos INTEGER NOT NULL,
  descricao TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS medalhas (
  id INTEGER PRIMARY KEY,
  aluno_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  professor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  tipo_id INTEGER NOT NULL REFERENCES tipos_medalha(id),
  mensagem TEXT NOT NULL DEFAULT '',
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_medalhas_aluno ON medalhas(aluno_id);

-- Quando cada aluno desbloqueou cada conquista (para mostrar no feed).
-- anunciar = 0: conquista antiga, registrada sem aparecer no feed.
CREATE TABLE IF NOT EXISTS conquistas_alunos (
  id INTEGER PRIMARY KEY,
  aluno_id INTEGER NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,
  conquista TEXT NOT NULL,
  anunciar INTEGER NOT NULL DEFAULT 1,
  criado_em TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (aluno_id, conquista)
);

CREATE INDEX IF NOT EXISTS idx_posts_data ON posts(criado_em);
CREATE INDEX IF NOT EXISTS idx_medalhas_data ON medalhas(criado_em);

CREATE TABLE IF NOT EXISTS avisos (
  id INTEGER PRIMARY KEY,
  autor_id INTEGER REFERENCES usuarios(id) ON DELETE SET NULL,
  titulo TEXT NOT NULL,
  texto TEXT NOT NULL,
  fixado INTEGER NOT NULL DEFAULT 0,
  criado_em TEXT NOT NULL DEFAULT (datetime('now'))
);
`);

// Mural: guarda o último aviso que cada pessoa já viu, para mostrar quantos são novos.
// Em bancos antigos, quem já tinha conta começa com tudo marcado como lido.
if (!db.prepare('PRAGMA table_info(usuarios)').all().some((c) => c.name === 'mural_visto_id')) {
  db.exec(`
    ALTER TABLE usuarios ADD COLUMN mural_visto_id INTEGER NOT NULL DEFAULT 0;
    UPDATE usuarios SET mural_visto_id = (SELECT IFNULL(MAX(id), 0) FROM avisos);
  `);
}

// Dados iniciais: tipos de medalha e conta da faculdade.
if (db.prepare('SELECT COUNT(*) AS n FROM tipos_medalha').get().n === 0) {
  const inserir = db.prepare('INSERT INTO tipos_medalha (nome, emoji, pontos, descricao) VALUES (?, ?, ?, ?)');
  for (const m of MEDALHAS_PADRAO) inserir.run(m.nome, m.emoji, m.pontos, m.descricao);
}

if (!db.prepare("SELECT 1 FROM usuarios WHERE papel = 'admin'").get()) {
  if (process.env.NODE_ENV === 'production' && !process.env.ADMIN_SENHA) {
    throw new Error('Defina a variável ADMIN_SENHA antes de colocar o Maxx no ar (a senha padrão é pública).');
  }
  db.prepare("INSERT INTO usuarios (nome, email, senha_hash, papel, bio) VALUES (?, ?, ?, 'admin', ?)").run(
    config.FACULDADE,
    config.ADMIN_EMAIL,
    hashSenha(config.ADMIN_SENHA),
    'Conta oficial da faculdade',
  );
  console.log(`Conta da faculdade criada: ${config.ADMIN_EMAIL} / senha: ${config.ADMIN_SENHA} (troque depois!)`);
}

module.exports = db;

// Regras de pontuação e conquistas do Maxx.

// Pontos por ação.
const PONTOS = {
  post: 10, // cada post publicado
  comentario: 3, // por post de colega comentado (só conta 1 vez por post)
  curtida: 2, // cada curtida recebida de outra pessoa
};

// Conquistas automáticas: quando o aluno chega na meta, ganha o bônus.
// conta = o que é contado (posts, comentarios, curtidas ou medalhas); meta = quanto precisa.
const CONQUISTAS = [
  { id: 'primeiro_post', emoji: '📸', nome: 'Primeiro clique', descricao: 'Publicou o primeiro post', bonus: 20, conta: 'posts', meta: 1 },
  { id: 'fotografo', emoji: '🎞️', nome: 'Fotógrafo do campus', descricao: 'Publicou 10 posts', bonus: 50, conta: 'posts', meta: 10 },
  { id: 'bom_de_papo', emoji: '💬', nome: 'Bom de papo', descricao: 'Comentou em 10 posts de colegas', bonus: 30, conta: 'comentarios', meta: 10 },
  { id: 'popular', emoji: '❤️', nome: 'Popular', descricao: 'Recebeu 50 curtidas', bonus: 50, conta: 'curtidas', meta: 50 },
  { id: 'estrela', emoji: '🌟', nome: 'Estrela da UniMax', descricao: 'Recebeu 200 curtidas', bonus: 100, conta: 'curtidas', meta: 200 },
  { id: 'medalhista', emoji: '🏅', nome: 'Medalhista', descricao: 'Ganhou a primeira medalha de um professor', bonus: 20, conta: 'medalhas', meta: 1 },
  { id: 'colecionador', emoji: '🏆', nome: 'Colecionador', descricao: 'Ganhou 5 medalhas de professores', bonus: 60, conta: 'medalhas', meta: 5 },
];

// Medalhas que os professores podem dar (criadas no banco na primeira execução).
const MEDALHAS_PADRAO = [
  { nome: 'Excelência acadêmica', emoji: '🥇', pontos: 50, descricao: 'Desempenho excepcional na disciplina' },
  { nome: 'Projeto destaque', emoji: '🚀', pontos: 40, descricao: 'Entregou um projeto que se destacou' },
  { nome: 'Ideia brilhante', emoji: '💡', pontos: 30, descricao: 'Trouxe uma ideia ou solução criativa' },
  { nome: 'Ajudou os colegas', emoji: '🤝', pontos: 30, descricao: 'Ajudou a turma a aprender' },
  { nome: 'Participação em aula', emoji: '🙋', pontos: 20, descricao: 'Participou ativamente das aulas' },
];

module.exports = { PONTOS, CONQUISTAS, MEDALHAS_PADRAO };

