399	function telaMural(req, res, { erro, status } = {}) {
400	  const avisos = listarAvisos();
401	  const vistoAte = req.usuario.mural_visto_id;
402	  for (const a of avisos) {
403	    a.novo = a.id > vistoAte && a.autor_id !== req.usuario.id;
404	    a.podeApagar = podeApagarAviso(req.usuario, a);
405	  }
406	  // Abriu o mural: tudo o que está nele passa a contar como lido.
