395	    <ul class="medalhas">
396	      ${medalhas.map(
397	        (m) => html`<li><span class="emoji">${m.emoji}</span><div><strong>${m.nome}</strong> <span class="pts">+${m.pontos}</span>
398	          <small class="muted">por ${m.professor_nome || 'professor(a)'} · ${tempoRelativo(m.criado_em)}</small>
399	          ${m.mensagem ? html`<p>“${m.mensagem}”</p>` : ''}</div></li>`,
