430	function faltaQuanto(c, s) {
431	  const falta = c.meta - s[c.conta];
432	  const [um, varios] = NOMES_CONTA[c.conta];
433	  return `${falta === 1 ? 'Falta' : 'Faltam'} ${plural(falta, um, varios)}`;
