538	    <label>Nome<input name="nome" value="${usuario.nome}" required maxlength="60"></label>
539	    ${usuario.papel !== 'admin' ? html`<label>Curso<select name="curso" required>${opcoesCurso(usuario.curso)}</select></label>` : ''}
540	    <label>Bio<textarea name="bio" rows="3" maxlength="300">${usuario.bio}</textarea></label>
541	    <button class="btn">Salvar</button>
542	  </form>
