549	const linkRanking = (curso) => (curso ? `/ranking?curso=${encodeURIComponent(curso)}` : '/ranking');
550	
551	// Abas: Geral, o curso do aluno e depois os outros cursos.
552	function abasRanking({ curso, porCurso, usuario, totalGeral }) {
