568	  const noCurso = meuCurso.find((a) => a.id === usuario.id);
569	  if (!noGeral) return '';
570	  const resumo = html`<div class="numeros numeros-3">
571	    <div><strong>${fmt(noGeral.total)}</strong><span>seus pontos</span></div>
572	    <a href="${linkRanking('')}"><strong>${noGeral.posicao}º</strong><span>de ${geral.length} no geral</span></a>
573	    <a href="${linkRanking(usuario.curso)}"><strong>${noCurso ? `${noCurso.posicao}º` : '–'}</strong><span>de ${meuCurso.length} no curso</span></a>
574	  </div>`;
