599	    <span class="pos">${medalhaPosicao(a.posicao)}</span>
600	    <a href="/u/${a.id}" class="usuario-link">${avatar(a)}<span><strong>${a.nome}</strong>${a.id === usuario.id ? html` <span class="selo selo-oficial">Você</span>` : ''}${mostrarCurso ? html`<small>${a.curso}</small>` : ''}</span></a>

